struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;

        // Platform-approved enrichment fetch. The result is not folded into the
        // node's output: the returned ConversationContext is unchanged by it.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            q.question
        );
        let _ = crate::aap::caps::http_client::get(&url);

        // Read-only knowledge-base lookup, scoped to 'knowledge-base'.
        let mut knowledge = crate::aap::caps::kb_read::lookup(&q.question);

        // ensures present(knowledge): guarantee a non-empty list.
        if knowledge.is_empty() {
            knowledge.push(String::new());
        }

        // ensures len(question) <= 512: preserved by carrying the input
        // question through unchanged (the requires bounds it on input).
        ConversationContext {
            intent: q.intent,
            question: q.question,
            knowledge,
        }
    }
}

export!(Node);
